import { Component, computed, effect, inject, input, signal, untracked } from '@angular/core';
import { DecimalPipe } from '@angular/common';
import type { Subscription } from 'rxjs';

import { ProductDetail as ProductDetailModel, ProductsApi } from '../../core/api/products.api';
import { CartService } from '../cart/cart.service';

@Component({
  selector: 'app-product-detail',
  imports: [DecimalPipe],
  templateUrl: './product-detail.html',
  styleUrl: './product-detail.scss',
})
export class ProductDetail {
  private readonly productsApi = inject(ProductsApi);
  private readonly cartService = inject(CartService);
  private subscription: Subscription | undefined;

  readonly id = input.required<string>();

  protected readonly product = signal<ProductDetailModel | null>(null);
  protected readonly loading = signal(false);
  protected readonly notFound = signal(false);
  protected readonly error = signal(false);

  protected readonly ratingAuthorName = signal('');
  protected readonly ratingValue = signal(5);
  protected readonly ratingSubmitting = signal(false);
  protected readonly ratingError = signal<string | null>(null);

  protected readonly selectedSupplierId = signal<string | null>(null);
  protected readonly quantity = signal(1);
  protected readonly addedToCartMessage = signal<string | null>(null);

  protected readonly canAddToCart = computed(() => {
    const supplierId = this.selectedSupplierId();
    const quantity = this.quantity();
    return supplierId !== null && Number.isInteger(quantity) && quantity >= 1;
  });

  constructor() {
    effect((onCleanup) => {
      const id = this.id();
      this.loadProduct(id);
      onCleanup(() => this.subscription?.unsubscribe());
    });
  }

  private loadProduct(id: string, options: { resetFirst: boolean } = { resetFirst: true }): void {
    if (options.resetFirst) {
      this.product.set(null);
      this.notFound.set(false);
      this.error.set(false);
      this.selectedSupplierId.set(null);
      this.quantity.set(1);
      this.addedToCartMessage.set(null);
      this.ratingAuthorName.set('');
      this.ratingValue.set(5);
      this.ratingSubmitting.set(false);
      this.ratingError.set(null);
    }
    this.loading.set(true);
    this.subscription?.unsubscribe();
    this.subscription = this.productsApi.getProduct(id).subscribe({
      next: (product) => {
        if (this.id() !== id) {
          return;
        }
        this.product.set(product);
        const stillOffered = untracked(() => product.offers.some((o) => o.supplierId === this.selectedSupplierId()));
        if (!stillOffered) {
          this.selectedSupplierId.set(product.offers[0]?.supplierId ?? null);
          this.addedToCartMessage.set(null);
        }
        this.loading.set(false);
      },
      error: (err) => {
        if (this.id() !== id) {
          return;
        }
        this.loading.set(false);
        if (err?.status === 404) {
          this.notFound.set(true);
        } else {
          this.error.set(true);
        }
      },
    });
  }

  protected submitRating(): void {
    const id = this.id();
    this.ratingSubmitting.set(true);
    this.ratingError.set(null);
    this.productsApi.submitRating(id, this.ratingAuthorName(), this.ratingValue()).subscribe({
      next: () => {
        if (this.id() !== id) {
          return;
        }
        this.ratingSubmitting.set(false);
        this.ratingAuthorName.set('');
        this.loadProduct(id, { resetFirst: false });
      },
      error: () => {
        if (this.id() !== id) {
          return;
        }
        this.ratingSubmitting.set(false);
        this.ratingError.set('Bewertung konnte nicht gespeichert werden. Bitte überprüfen Sie Ihre Eingabe.');
      },
    });
  }

  protected addToCart(): void {
    const product = this.product();
    const supplierId = this.selectedSupplierId();
    const quantity = this.quantity();
    if (product === null || supplierId === null || !Number.isInteger(quantity) || quantity < 1) {
      return;
    }
    const offer = product.offers.find((o) => o.supplierId === supplierId);
    if (offer === undefined) {
      return;
    }
    this.cartService.addItem({
      productId: product.id,
      productName: product.name,
      supplierId: offer.supplierId,
      supplierName: offer.supplierName,
      unitPrice: offer.price,
      quantity,
    });
    this.addedToCartMessage.set(`${quantity} × ${product.name} (${offer.supplierName}) wurde in den Warenkorb gelegt.`);
  }
}

@if (loading()) {
  <p class="product-detail__loading">Lädt…</p>
}

@if (notFound()) {
  <p class="product-detail__not-found">Dieses Produkt wurde nicht gefunden.</p>
}

@if (error()) {
  <p class="product-detail__error">Das Produkt konnte nicht geladen werden. Bitte versuchen Sie es später erneut.</p>
}

@if (product(); as product) {
  <article class="product-detail">
    <h1 class="product-detail__name">{{ product.name }}</h1>
    <p class="product-detail__category">{{ product.categoryName }} / {{ product.subcategoryName }}</p>
    <p class="product-detail__description">{{ product.description }}</p>

    @if (product.properties.length > 0) {
      <dl class="product-detail__properties">
        @for (property of product.properties; track property.name) {
          <dt>{{ property.name }}</dt>
          <dd>{{ property.value }}</dd>
        }
      </dl>
    }

    <p class="product-detail__rating">
      @if (product.averageRating !== null) {
        {{ product.averageRating | number: '1.1-1' }} ({{ product.ratingCount }} Bewertungen)
      } @else {
        Noch keine Bewertungen
      }
    </p>

    @if (product.offers.length > 0) {
      <form class="product-detail__add-to-cart-form" (submit)="$event.preventDefault(); addToCart()">
        <ul class="product-detail__offers">
          @for (offer of product.offers; track offer.supplierId) {
            <li class="product-detail__offer">
              <label>
                <input
                  type="radio"
                  name="supplier"
                  class="product-detail__offer-radio"
                  [value]="offer.supplierId"
                  [checked]="selectedSupplierId() === offer.supplierId"
                  (change)="selectedSupplierId.set(offer.supplierId)"
                />
                <span class="product-detail__offer-supplier">{{ offer.supplierName }}</span>
                <span class="product-detail__offer-price">{{ offer.price | number: '1.2-2' }} €</span>
              </label>
            </li>
          }
        </ul>
        <label>
          Menge
          <input
            class="product-detail__quantity-input"
            type="number"
            min="1"
            step="1"
            [value]="quantity()"
            (input)="quantity.set(+$any($event.target).value)"
          />
        </label>
        <button class="product-detail__add-to-cart-submit" type="submit" [disabled]="!canAddToCart()">
          In den Warenkorb
        </button>
        @if (addedToCartMessage()) {
          <p class="product-detail__add-to-cart-confirmation">{{ addedToCartMessage() }}</p>
        }
      </form>
    } @else {
      <p class="product-detail__no-offers">Aktuell kein Lieferant verfügbar.</p>
    }

    <section class="product-detail__rating-form">
      <h2>Bewertung abgeben</h2>
      <form (submit)="$event.preventDefault(); submitRating()">
        <label>
          Name
          <input
            class="product-detail__rating-author-input"
            type="text"
            [value]="ratingAuthorName()"
            (input)="ratingAuthorName.set($any($event.target).value)"
          />
        </label>
        <label>
          Bewertung
          <select
            class="product-detail__rating-value-select"
            [value]="ratingValue()"
            (change)="ratingValue.set(+$any($event.target).value)"
          >
            @for (value of [1, 2, 3, 4, 5]; track value) {
              <option [value]="value">{{ value }}</option>
            }
          </select>
        </label>
        <button class="product-detail__rating-submit" type="submit" [disabled]="ratingSubmitting()">
          Bewertung abschicken
        </button>
      </form>
      @if (ratingError()) {
        <p class="product-detail__rating-error">{{ ratingError() }}</p>
      }
    </section>
  </article>
}

