  - [ ] **Bestehende `addItem`-Logik nicht verändern** — diese Story erweitert `CartService` nur um die drei genannten Mitglieder, ändert keine bestehende Methode/Signatur.

- [ ] Task 2: Neue Komponente `Cart` als geroutete Warenkorbansicht (AC: #1, #2, #3, #4, #5)
  - [ ] Neue Dateien `seed-b-frontend/src/app/features/cart/cart.ts`, `cart.html`, `cart.scss`, `cart.spec.ts` — analog zum bestehenden Muster gerouteter Top-Level-Components (`features/catalog/catalog.ts`, `features/product-detail/product-detail.ts`): eigenständige `@Component` mit `imports: [DecimalPipe]`, kein `HttpClient`-Zugriff (Warenkorb bleibt reiner Frontend-State, AD-3).
  - [ ] `cart.ts`:
    ```ts
    import { Component, inject, signal } from '@angular/core';
    import { DecimalPipe } from '@angular/common';

    import { CartItem, CartService } from './cart.service';

    @Component({
      selector: 'app-cart',
      imports: [DecimalPipe],
      templateUrl: './cart.html',
      styleUrl: './cart.scss',
    })
    export class Cart {
      private readonly cartService = inject(CartService);

      protected readonly items = this.cartService.items;
      protected readonly totalAmount = this.cartService.totalAmount;
      protected readonly quantityErrors = signal<Record<string, string>>({});

      protected lineTotal(item: CartItem): number {
        return item.unitPrice * item.quantity;
      }

      protected itemKey(item: CartItem): string {
        return `${item.productId}:${item.supplierId}`;
      }

      protected onQuantityChange(item: CartItem, value: string): void {
        const quantity = +value;
        const key = this.itemKey(item);
        const ok = this.cartService.updateQuantity(item.productId, item.supplierId, quantity);
        this.quantityErrors.update((errors) => {
          const next = { ...errors };
          if (ok) {
            delete next[key];
          } else {
            next[key] = 'Ungültige Menge. Bitte eine ganze Zahl ab 1 eingeben.';
          }
          return next;
        });
      }

      protected onRemove(item: CartItem): void {
        const key = this.itemKey(item);
        this.cartService.removeItem(item.productId, item.supplierId);
        this.quantityErrors.update((errors) => {
          const next = { ...errors };
          delete next[key];
          return next;
        });
      }
    }
    ```
    `items`/`totalAmount` werden direkt als Referenz auf die Service-Signale exponiert (kein Zwischenkopieren) — exakt das Muster, das `CartService.items` selbst für `_items.asReadonly()` verwendet. `quantityErrors` ist ein lokaler, pro Position (`productId:supplierId`-Schlüssel) geführter Fehlertext-State, der **nur in der Component** existiert — der Service kennt keine UI-Texte (Trennung State vs. Präsentation, konsistent mit der übrigen Architektur).
